// Checkout.test.tsx
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock contexts - even Zeus must provide proper dependencies
const mockClearCart = vi.fn();
const mockProcessPayment = vi.fn();

vi.mock('./CartContext', () => ({
  useCart: () => ({
    items: [{ id: '1', name: 'Widget', price: 29.99 }],
    total: 29.99,
    clearCart: mockClearCart,
  }),
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment }),
}));

const validShipping = {
  street: '123 Olympus Lane',
  city: 'Athens',
  state: 'CA',
  zip: '90210',
};

const validPayment = {
  cardNumber: '4111111111111111',
  expiry: '12/25',
  cvv: '123',
  nameOnCard: 'Zeus Thunderer',
};

describe('Checkout Component', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-12345' });
  });

  // 1. HAPPY PATH - Complete checkout flow
  describe('Happy Path', () => {
    it('completes full checkout flow from shipping to confirmation', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();
      render(<Checkout onComplete={onComplete} />);

      // Arrange & Act - Shipping step
      await user.type(screen.getByLabelText(/street address/i), validShipping.street);
      await user.type(screen.getByLabelText(/city/i), validShipping.city);
      await user.selectOptions(screen.getByLabelText(/state/i), validShipping.state);
      await user.type(screen.getByLabelText(/zip code/i), validShipping.zip);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Assert - Payment step visible
      expect(screen.getByRole('heading', { name: /payment details/i })).toBeInTheDocument();

      // Act - Payment step
      await user.type(screen.getByLabelText(/card number/i), validPayment.cardNumber);
      await user.type(screen.getByLabelText(/expiry/i), validPayment.expiry);
      await user.type(screen.getByLabelText(/cvv/i), validPayment.cvv);
      await user.type(screen.getByLabelText(/name on card/i), validPayment.nameOnCard);
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Assert - Review step
      expect(screen.getByRole('heading', { name: /review your order/i })).toBeInTheDocument();
      expect(screen.getByText(/widget/i)).toBeInTheDocument();

      // Act - Place order
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Assert - Confirmation
      expect(await screen.findByText(/order confirmed/i)).toBeInTheDocument();
      expect(onComplete).toHaveBeenCalledWith('ORD-12345');
    });
  });

  // 2. FORM VALIDATION
  describe('Form Validation', () => {
    it('displays shipping validation errors for empty fields', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
      expect(screen.getByText(/city is required/i)).toBeInTheDocument();
      expect(screen.getByLabelText(/street/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('validates ZIP code format', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });

    it('validates card number must be 16 digits', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      // Navigate to payment step first
      await fillShippingForm(user);

      await user.type(screen.getByLabelText(/card number/i), '1234');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      expect(screen.getByText(/valid 16-digit card number required/i)).toBeInTheDocument();
    });
  });

  // 3. ERROR STATES AND RECOVERY
  describe('Error States', () => {
    it('displays payment error and allows retry', async () => {
      mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
      const user = userEvent.setup();
      render(<Checkout />);

      await fillShippingForm(user);
      await fillPaymentForm(user);
      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(await screen.findByRole('alert')).toHaveTextContent(/card declined/i);

      // Retry succeeds
      mockProcessPayment.mockResolvedValueOnce({ orderId: 'ORD-99999' });
      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(await screen.findByText(/order confirmed/i)).toBeInTheDocument();
    });
  });

  // 4. LOADING AND DISABLED STATES
  describe('Loading States', () => {
    it('disables buttons and shows loading indicator during submission', async () => {
      mockProcessPayment.mockImplementation(() => new Promise(() => {})); // Never resolves
      const user = userEvent.setup();
      render(<Checkout />);

      await fillShippingForm(user);
      await fillPaymentForm(user);
      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
      expect(screen.getByRole('button', { name: /back/i })).toBeDisabled();
    });
  });

  // 5. ACCESSIBILITY
  describe('Accessibility', () => {
    it('has no accessibility violations on shipping step', async () => {
      const { container } = render(<Checkout />);
      const results = await axe(container);
      expect(results).toHaveNoViolations();
    });

    it('announces errors via role="alert"', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      const alerts = screen.getAllByRole('alert');
      expect(alerts.length).toBeGreaterThan(0);
    });
  });

  // 6. EDGE CASES
  describe('Edge Cases', () => {
    it('shows empty cart message and continue shopping button', () => {
      vi.mocked(useCart).mockReturnValue({ items: [], total: 0, clearCart: mockClearCart });
      render(<Checkout onCancel={vi.fn()} />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
      expect(screen.getByRole('button', { name: /continue shopping/i })).toBeInTheDocument();
    });
  });
});

// Helpers - No edge case escapes my scales
async function fillShippingForm(user: ReturnType<typeof userEvent.setup>) {
  await user.type(screen.getByLabelText(/street address/i), validShipping.street);
  await user.type(screen.getByLabelText(/city/i), validShipping.city);
  await user.selectOptions(screen.getByLabelText(/state/i), validShipping.state);
  await user.type(screen.getByLabelText(/zip code/i), validShipping.zip);
  await user.click(screen.getByRole('button', { name: /continue to payment/i }));
}

async function fillPaymentForm(user: ReturnType<typeof userEvent.setup>) {
  await user.type(screen.getByLabelText(/card number/i), validPayment.cardNumber);
  await user.type(screen.getByLabelText(/expiry/i), validPayment.expiry);
  await user.type(screen.getByLabelText(/cvv/i), validPayment.cvv);
  await user.type(screen.getByLabelText(/name on card/i), validPayment.nameOnCard);
  await user.click(screen.getByRole('button', { name: /review order/i }));
}
